{
  "name": "opencode-gentle-ai-updater",
  "version": "0.3.0",
  "description": "OpenCode plugin that detects pending Gentle AI updates and applies them on demand.",
  "type": "module",
  "license": "MIT",
  "author": "Bairon M. <bvironn@icloud.com>",
  "keywords": [
    "opencode",
    "opencode-plugin",
    "gentle-ai",
    "updater"
  ],
  "repository": {
    "type": "git",
    "url": "git+https://github.com/bvironn/opencode-gentle-ai-updater.git"
  },
  "homepage": "https://github.com/bvironn/opencode-gentle-ai-updater#readme",
  "bugs": {
    "url": "https://github.com/bvironn/opencode-gentle-ai-updater/issues"
  },
  "main": "./dist/index.js",
  "module": "./dist/index.js",
  "types": "./dist/index.d.ts",
  "exports": {
    ".": {
      "types": "./dist/index.d.ts",
      "import": "./dist/index.js"
    }
  },
  "files": [
    "dist",
    "tui",
    "commands",
    "README.md",
    "LICENSE"
  ],
  "scripts": {
    "build": "bun build src/index.ts --target=bun --format=esm --external @opencode-ai/plugin --outdir=dist && tsc --emitDeclarationOnly",
    "typecheck": "tsc --noEmit",
    "prepare": "bun run build"
  },
  "peerDependencies": {
    "@opencode-ai/plugin": ">=1.17.0 <2"
  },
  "devDependencies": {
    "@opencode-ai/plugin": "^1.17.3",
    "@types/bun": "^1.3.14",
    "typescript": "^5.9.3"
  }
}
